import{_ as i,l as s,o as e,c as l,v as r,p as n,x as t,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"路由器架构","description":"","frontmatter":{"title":"路由器架构","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/router-architecture.md","filePath":"cs/router-architecture.md","lastUpdated":1789023840000}'),h={name:"cs/router-architecture.md"};function B(u,a,P,A,I,_){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="路由器架构" tabindex="-1">路由器架构 <a class="header-anchor" href="#路由器架构" aria-label="Permalink to &quot;路由器架构&quot;">​</a></h1><div class="epigraph"><p>控制面算表，转发面按线速查表改头出队；两者用 FIB 快照耦合，慢路径例外上送。</p><footer>—— 据 Kurose and Ross 路由器内部；Partridge et al., A 50-Gb/s IP Router, IEEE/ACM ToN 1998 整理</footer></div><p><a href="/cs/switch-fabric">交换机架构</a> 已给二层结构。<a href="/cs/ttl-traceroute">上一课</a> 结束选路课序。缺口是<strong>路由器怎么拆</strong>：路由处理器跑 OSPF/BGP，线卡查 LPM、TTL、ACL。本课不把 TCAM 电路写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若每包都问 CPU，吉比特已不可及。架构：控制面维护 RIB，下发 FIB 到转发 ASIC；包：解析 → LPM → 改 TTL/MAC → fabric → 出口 QoS。例外：选项、过期、BGP 包上送。与交换机同构，多了三层与隧道封装。过订购同样存在。卫星高延迟不改内部时隙，只改会话数。</p><p><span class="marginnote">早期工作站路由器是软件；当代盒是分布式线卡。本课不点名型号。</span></p><h3 id="rib-与-fib-分离" tabindex="-1">RIB 与 FIB 分离 <a class="header-anchor" href="#rib-与-fib-分离" aria-label="Permalink to &quot;RIB 与 FIB 分离&quot;">​</a></h3><p>控制面算表，线卡线速查。FIB 编程延迟造成瞬态不一致。例外上送，热路径不进通用内核。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：RP ↔ 线卡 FIB。对照主机<a href="/cs/socket-api">套接字</a>：主机每包进内核；路由器数据面绕开通用 OS 热路径。BFD 可在线卡加速，仍属控制。</p>',10)),(e(),n(p,null,{default:t(()=>[d(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20RIB%5B%22%E6%8E%A7%E5%88%B6%E9%9D%A2%20RIB%22%5D%20--%3E%20FIB%5B%22%E7%BA%BF%E5%8D%A1%20FIB%22%5D%0A%20%20PKT%5B%22%E5%8C%85%22%5D%20--%3E%20ASIC%5B%22%E8%A7%A3%E6%9E%90%20LPM%20QoS%22%5D%0A%20%20ASIC%20--%3E%20FAB%5B%22%E7%BB%93%E6%9E%84%22%5D%0A%20%20EX%5B%22%E4%BE%8B%E5%A4%96%22%5D%20--%3E%20CPU%5B%22%E4%B8%8A%E9%80%81%20RP%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>BGP 收敛先改 RIB 再编程 FIB，数据面滞后是「已通告但未转发」窗口。ECMP 组作为 FIB 下一跳组下发。EVPN Type 2 同样下到转发表。PMTUD ICMP 由控制面或线卡生成，取决于实现。</p><p>冗余 RP：ISSU/NSF 让转发在控制面重启时继续，对象是可用性。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入网络处理器微码。TCAM 查表是下一课。后课默认：RIB/FIB 分离；线速在 ASIC。</p><p>「软件路由器」用 DPDK 把主机变成线卡，架构角色不变。</p><p>上一课留下的缺口在本课收口；「路由器架构」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/tcam-lookup">TCAM 查表</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>控制面算，转发面查，FIB 是契约。</li><li>例外上送；热路径不进通用内核。</li><li>FIB 编程延迟造成瞬态不一致。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Kurose and Ross；Partridge et al., 1998。</li></ul>',10))])}const m=i(h,[["render",B]]);export{f as __pageData,m as default};
